Declaration order decides the initialisation order, not the list order. <br><pre><code>#include &lt;iostream&gt;
#include &lt;string&gt;

struct Curve {
    const std::string&amp; ccy;    // reference member
    const int days;            // const member
    Curve(const std::string&amp; c, int d) : ccy(c), days(d) {}   // must use the list
};

int main() {
    std::string usd = "USD";
    Curve c(usd, 365);
    std::cout &lt;&lt; c.ccy &lt;&lt; ' ' &lt;&lt; c.days &lt;&lt; '\n';
}
</code></pre><b>Output:</b><pre>USD 365</pre>Without a list entry, a reference member has no default and the compiler rejects the constructor.<br><b>Interview trap:</b> a reference member makes the class non-assignable as well, so the implicit copy assignment is deleted.

Before C++17 the definition had to go in exactly one <code>.cpp</code> file. A missing definition is a link error, not a compile error.<br><pre><code>#include &lt;iostream&gt;
#include &lt;string&gt;
#include &lt;utility&gt;

class Trade {
public:
    inline static int live_count = 0;          // one object shared by all instances (C++17)
    static int created() { return live_count; } // no this pointer
    std::string id;
    explicit Trade(std::string s) : id(std::move(s)) { ++live_count; }
    ~Trade() { --live_count; }
};

int main() {
    Trade a{"T1"};
    {
        Trade b{"T2"};
        std::cout &lt;&lt; Trade::live_count &lt;&lt; '\n';
    }
    std::cout &lt;&lt; Trade::created() &lt;&lt; ' ' &lt;&lt; a.live_count &lt;&lt; '\n';
}
</code></pre><b>Output:</b><pre>2
1 1</pre><b>Interview trap:</b> a static member function cannot be <code>const</code> or call a non-static member without an object argument, so the usual Python instance-method pattern does not carry over.
